{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Berkeley Rent Ordinance rent control coverage","requirement":"Landlords of most multifamily units built before 1980 are fully covered by rent control and may raise rent only as the ordinance allows; newer construction, most condominiums and post-1996 single-family tenancies are not rent-controlled.","key_value":null,"coverage_conditions":"Most multifamily units built before 1980 are fully covered; new construction with a certificate of occupancy after June 1980, most condominiums, single-family tenancies beginning on or after January 1, 1996 and certain subsidized units are not rent-controlled.","applicability":{"built_on_or_before":"1980","built_after":"1980-06","date_basis":"certificate_of_occupancy","min_units":null,"max_units":null,"owner_dependent":true,"other":"Single family homes with tenancies that began before 1996 are fully covered"},"exemptions":"Golden Duplex owner-occupied on December 31, 1979 with a current owner occupant; units where the owner shares a kitchen or bath; ADU properties with one unit owner-occupied for tenancies started after Nov 7, 2018; university dormitories; nonprofit cooperatives.","penalty":null,"effective_date":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes","interaction":null,"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Berkeley Rent Ordinance just cause for eviction coverage","requirement":"A landlord of a fully or partially covered unit may end a tenancy only for just cause under the ordinance, including newer construction, condominiums and single-family homes; exempt unit types are not covered.","key_value":null,"coverage_conditions":"Just cause applies to all fully and partially covered unit types, including multifamily units built before 1980, units built after June 1980, condominiums, single-family homes, rooming houses and listed subsidized units.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Exempt unit types (owner-occupied Golden Duplex, owner-shared kitchen or bath, owner-occupied ADU tenancies after Nov 7, 2018, dormitories, nonprofit cooperatives) are not covered"},"exemptions":"Golden Duplex owner-occupied on December 31, 1979 with a current owner occupant; units where the owner shares a kitchen or bath and lived on the property when the tenancy started; ADU owner-occupied properties for tenancies started after Nov 7, 2018; university dormitories; nonprofit cooperatives.","penalty":null,"effective_date":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"New construction: units that were built and received a Certificate of Occupancy after June 1980** Partially Covered Yes No Yes Yes","interaction":null,"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"security_deposits","lifecycle":"enacted","title":"Berkeley Rent Ordinance security deposit interest coverage","requirement":"Landlords of fully and partially covered units must pay interest on tenants' security deposits; units listed as exempt are not subject to the security deposit interest requirement.","key_value":null,"coverage_conditions":"Security deposit interest applies to fully and partially covered unit types, including multifamily units built before 1980, units built after June 1980, condominiums, single-family homes, rooming houses and listed subsidized units.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Exempt unit types receive no security deposit interest"},"exemptions":"Golden Duplex owner-occupied on December 31, 1979 with a current owner occupant; units where the owner shares a kitchen or bath and lived on the property when the tenancy started; ADU owner-occupied properties for tenancies started after Nov 7, 2018; university dormitories; nonprofit cooperatives.","penalty":null,"effective_date":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"Security Deposit Interest Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes","interaction":null,"confidence":0.6,"conflict_flag":false,"conflict_note":null}
